import type { BankQuestion } from "@/lib/bank";

/** Plant Physiology (Biology (NEET)): 133 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-plant-physiology-1","question":"The primary acceptor of CO₂ in the Calvin cycle of C3 plants is:","options":["Phosphoenolpyruvate (PEP) in mesophyll","Oxaloacetic acid (OAA)","3-Phosphoglyceric acid (PGA)","Ribulose-1,5-bisphosphate (RuBP)"],"answer":3,"explanation":"In C3 plants RuBP (a 5-carbon sugar) accepts CO₂ in a reaction catalysed by RuBisCO, giving two molecules of 3-PGA. PEP is the acceptor in C4 and CAM plants.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-physiology-2","question":"The light reactions of photosynthesis take place in the:","options":["Stroma of the chloroplast","Inner mitochondrial membrane","Thylakoid membranes (grana)","Cytosol"],"answer":2,"explanation":"Photosystems I and II, the electron transport chain and ATP synthase are embedded in the thylakoid membranes; the stroma is the site of the Calvin cycle (dark reactions).","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-physiology-3","question":"Which plant growth regulator is a gas and promotes fruit ripening?","options":["Abscisic acid","Ethylene","Gibberellin","Cytokinin"],"answer":1,"explanation":"Ethylene (C₂H₄) is a simple gaseous PGR that hastens ripening of fruits, senescence and abscission. Ethephon, an aqueous source of ethylene, is sprayed on fruit to ripen it.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-physiology-4","question":"During glycolysis, the NET gain of ATP per molecule of glucose is:","options":["4","2","8","36"],"answer":1,"explanation":"Glycolysis uses 2 ATP (at the hexokinase and phosphofructokinase steps) and produces 4 ATP by substrate-level phosphorylation, so the net gain is 2 ATP, along with 2 NADH and 2 pyruvate.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-5","question":"Kranz anatomy, with large bundle-sheath cells surrounding the vascular bundles, is a feature of:","options":["C3 plants such as wheat and rice","Submerged aquatic angiosperms like Hydrilla","CAM plants such as Opuntia","C4 plants such as maize and sorghum"],"answer":3,"explanation":"C4 plants have Kranz (‘wreath’) anatomy: mesophyll cells fix CO₂ into OAA and the thick-walled bundle-sheath cells, rich in RuBisCO, run the Calvin cycle. C3 and CAM plants lack this arrangement.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-6","question":"Removal of the shoot apex causes lateral buds to sprout. This is because the apex normally produces:","options":["Cytokinin, which suppresses lateral buds","Ethylene, which inhibits bud growth","Auxin, which causes apical dominance","Abscisic acid, which keeps buds dormant"],"answer":2,"explanation":"Auxin from the apical bud inhibits the growth of lateral buds (apical dominance). Decapitation removes the auxin source and lateral buds grow; cytokinins actually promote lateral bud growth.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-7","question":"The translocation of sugars from source to sink through the phloem is best explained by the:","options":["Pressure-flow (mass-flow) hypothesis","Cohesion–tension (transpiration pull) theory","Root pressure theory","Apoplastic diffusion model"],"answer":0,"explanation":"Loading of sucrose at the source lowers the water potential of sieve tubes, water enters from xylem and the resulting hydrostatic pressure pushes sap toward the sink where sugar is unloaded. Cohesion–tension explains xylem ascent, not phloem transport.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-8","question":"Which mineral element is a structural constituent of the chlorophyll molecule?","options":["Iron","Manganese","Magnesium","Calcium"],"answer":2,"explanation":"Mg²⁺ sits at the centre of the porphyrin ring of chlorophyll. Iron is needed for chlorophyll synthesis but is not part of the molecule, so both deficiencies cause chlorosis.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-9","question":"The respiratory quotient (RQ) for complete oxidation of a fat such as tripalmitin is:","options":["Exactly 1.0","About 0.7","About 0.9","Greater than 1.0"],"answer":1,"explanation":"RQ = CO₂ evolved ÷ O₂ consumed. For tripalmitin: 2C₅₁H₉₈O₆ + 145 O₂ → 102 CO₂ + 98 H₂O, so RQ = 102/145 ≈ 0.7. Carbohydrates give 1.0; proteins about 0.9.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-10","question":"For one molecule of glucose completely oxidised, how many NADH + H⁺ and FADH₂ are produced in the citric acid (Krebs) cycle alone?","options":["3 NADH and 1 FADH₂","10 NADH and 2 FADH₂","8 NADH and 2 FADH₂","6 NADH and 2 FADH₂"],"answer":3,"explanation":"Each turn of the TCA cycle (one acetyl-CoA) gives 3 NADH, 1 FADH₂ and 1 GTP. One glucose gives two acetyl-CoA, so the cycle yields 6 NADH and 2 FADH₂. The total of 10 NADH per glucose includes 2 from glycolysis and 2 from the link reaction.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-11","question":"In a C4 plant, the enzyme RuBisCO is located in the:","options":["Mesophyll cells only","Bundle-sheath cells only","Both mesophyll and bundle-sheath cells","Guard cells"],"answer":1,"explanation":"Mesophyll cells of C4 plants have PEP carboxylase but no RuBisCO; the Calvin cycle with RuBisCO runs only in the bundle-sheath cells, where decarboxylation of the C4 acid keeps the CO₂ concentration high and suppresses photorespiration.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-12","question":"Which statement about photorespiration is INCORRECT?","options":["It begins when RuBisCO binds O₂ instead of CO₂, forming phosphoglycolate","It releases CO₂ and consumes ATP","It does not synthesise sugar or ATP","It occurs vigorously in C4 plants under high light"],"answer":3,"explanation":"Photorespiration is a wasteful process (RuBP + O₂ → one PGA + one 2-carbon phosphoglycolate) in C3 plants. C4 plants avoid it because the Calvin cycle is confined to bundle-sheath cells where CO₂ is concentrated.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-13","question":"To synthesise one molecule of glucose, the Calvin cycle requires:","options":["12 ATP and 6 NADPH","6 ATP and 12 NADPH","18 ATP and 12 NADPH","18 ATP and 18 NADPH"],"answer":2,"explanation":"Six turns of the cycle fix 6 CO₂. Each turn uses 3 ATP and 2 NADPH, so one glucose needs 18 ATP and 12 NADPH, all supplied by the light reactions.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-14","question":"When a ring of bark (including the phloem) is removed from a tree trunk, the tissue just ABOVE the ring swells after some days. This shows that:","options":["Water moves upward through the phloem and collects above the ring","Food moves down the phloem and accumulates above the cut","Xylem transport has stopped above the ring","Minerals move downward through the xylem"],"answer":1,"explanation":"Girdling removes the phloem but leaves the xylem; sugars moving down from the leaves pile up above the girdle, producing the swelling, while water still rises through the intact xylem.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-15","question":"A plant cell has a solute potential of −8 bars and a pressure potential of +3 bars. It is placed in a solution whose water potential is −3 bars. Which way will water move?","options":["Into the cell, as its Ψw (−5 bars) is lower than −3 bars","Out of the cell, because the cell’s water potential is −5 bars","No net movement, since the cell’s Ψw equals −3 bars too","Out of the cell, because solute potential (−8) is lower than −3"],"answer":0,"explanation":"Ψw = Ψs + Ψp = −8 + 3 = −5 bars for the cell. Water moves from higher to lower water potential, i.e. from the solution (−3 bars) into the cell (−5 bars). Option 4 wrongly ignores the pressure potential.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-16","question":"Which of the following elements is a MICRONUTRIENT for plants?","options":["Calcium","Magnesium","Phosphorus","Molybdenum"],"answer":3,"explanation":"Micronutrients (needed in less than 10 mmol per kg dry matter) are Fe, Mn, Cu, Mo, Zn, B, Cl and Ni. Ca, Mg and S are macronutrients.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-17","question":"Nitrogenase, the enzyme of biological nitrogen fixation, is:","options":["A copper–zinc protein that works best under aerobic conditions","A Mo–Fe protein that is highly sensitive to molecular oxygen","A haem protein that binds N₂ at high pO₂","An extracellular enzyme secreted into the soil"],"answer":1,"explanation":"Nitrogenase is a Mo–Fe protein that reduces N₂ to 2NH₃ using 8 e⁻ and 16 ATP; it is inactivated by O₂, which is why root nodules contain leghaemoglobin to scavenge oxygen.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-18","question":"The delay of leaf senescence (Richmond–Lang effect) and overcoming of apical dominance are attributed to:","options":["Auxin","Gibberellin","Cytokinin","Abscisic acid"],"answer":2,"explanation":"Cytokinins promote cell division, nutrient mobilisation, growth of lateral buds (countering auxin’s apical dominance) and delay leaf senescence. ABA, in contrast, promotes senescence and dormancy.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-19","question":"How many of the following statements about C4 plants are correct?\n(i) PEP carboxylase, the primary carboxylating enzyme, is present in mesophyll cells.\n(ii) Bundle-sheath cells have thick walls impervious to gaseous exchange.\n(iii) Bundle-sheath cells usually lack grana.\n(iv) Photorespiration does not occur in C4 plants.","options":["Only 1","Only 2","Only 3","All 4"],"answer":3,"explanation":"All four are correct: PEP carboxylase is in the mesophyll, bundle-sheath cells have thick walls impervious to gas and lack grana, and photorespiration does not occur in C4 plants, which is why they are more productive.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-20","question":"Match the plant growth regulator with its commercial/physiological use.\nA. Gibberellin — 1. Sprouting of potato tubers and synchronised fruit set in pineapple\nB. Cytokinin — 2. Speeding up malting in brewing\nC. Ethylene — 3. Stomatal closure under water stress\nD. Abscisic acid — 4. Promotes growth of lateral buds and delays senescence","options":["A-2, B-4, C-1, D-3","A-1, B-3, C-2, D-4","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3"],"answer":0,"explanation":"GA₃ hastens malting; cytokinins release lateral buds and delay senescence; ethylene breaks tuber dormancy and initiates flowering in pineapple; ABA, the stress hormone, closes stomata.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-21","question":"Assertion (A): C4 plants are more productive than C3 plants under high light and temperature.\nReason (R): In C4 plants, PEP carboxylase has a high affinity for CO₂ and RuBisCO functions in bundle-sheath cells where CO₂ is concentrated, so photorespiration is avoided.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The spatial separation of carboxylation (mesophyll, PEPcase) and the Calvin cycle (bundle sheath, RuBisCO under high CO₂) eliminates the oxygenase activity of RuBisCO, giving C4 plants their higher productivity and tolerance of stress.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-22","question":"Two molecules of glucose are completely oxidised aerobically. Count the molecules formed: CO₂ released, NADH + H⁺ formed (all stages) and FADH₂ formed.","options":["6 CO₂, 10 NADH, 2 FADH₂","12 CO₂, 20 NADH, 4 FADH₂","12 CO₂, 16 NADH, 4 FADH₂","12 CO₂, 12 NADH, 2 FADH₂"],"answer":1,"explanation":"Per glucose: 6 CO₂ (2 in the link reaction + 4 in TCA), 10 NADH (2 glycolysis + 2 link reaction + 6 TCA) and 2 FADH₂ (TCA). Doubling gives 12 CO₂, 20 NADH and 4 FADH₂.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-23","question":"How many of the following statements about stomata and transpiration are correct?\n(i) Stomatal opening is driven by K⁺ uptake into guard cells, which lowers their water potential.\n(ii) The inner wall of a guard cell (toward the pore) is thin, the outer wall is thick and elastic.\n(iii) Cellulose microfibrils in guard-cell walls are oriented longitudinally, making it easier for the cells to bulge outward when turgid.\n(iv) Abscisic acid promotes stomatal opening during drought.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only (i) is correct. The inner wall of a guard cell is thick and elastic and the outer wall thin, the microfibrils are oriented radially, and ABA closes stomata during water stress.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-24","question":"How many of the following statements about photoperiodism and vernalisation are correct?\n(i) The site of perception of light/dark duration is the leaf.\n(ii) A hormonal substance from the leaves migrates to the shoot apex to induce flowering.\n(iii) Vernalisation is the promotion of flowering by a period of low temperature.\n(iv) Winter varieties of wheat and barley are sown in autumn and flower in spring after exposure to cold.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four statements are NCERT facts. Photoperiod is perceived by leaves (though flowering occurs at the shoot apex), and vernalisation (as in winter cereals and biennials such as cabbage and carrot) requires cold exposure before flowering.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-25","question":"Match the scientist with the discovery in photosynthesis.\nA. Joseph Priestley — 1. Showed that the released O₂ comes from water, using purple and green sulphur bacteria\nB. Jan Ingenhousz — 2. Bell-jar experiment with mint plant, candle and mouse\nC. T. W. Engelmann — 3. Showed that only the green parts release O₂, and only in sunlight\nD. Cornelius van Niel — 4. Action spectrum using Cladophora and aerobic bacteria","options":["A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-3, B-2, C-1, D-4","A-1, B-3, C-4, D-2"],"answer":0,"explanation":"Priestley (1770) restored air with a mint plant; Ingenhousz showed light is essential; Engelmann used a prism and aerobic bacteria to find the action spectrum; van Niel inferred that O₂ comes from H₂O (2H₂A + CO₂ → 2A + CH₂O + H₂O).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-26","question":"Deficiency symptoms of which pair of elements appear FIRST in young leaves and growing tips rather than in older leaves?","options":["Nitrogen and potassium","Magnesium and nitrogen","Sulphur and calcium","Potassium and magnesium"],"answer":2,"explanation":"Elements that are relatively immobile in the plant (S, Ca) cannot be withdrawn from old tissue, so their deficiency shows first in young parts. Mobile elements (N, K, Mg) are exported from older leaves, which therefore show symptoms first.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-27","question":"How many of the following statements about the mitochondrial electron transport system are correct?\n(i) Cytochrome c is a small protein attached to the outer surface of the inner membrane and acts as a mobile carrier between complex III and complex IV.\n(ii) Complex IV (cytochrome c oxidase) contains cytochromes a and a₃ and two copper centres.\n(iii) The F₁ headpiece of ATP synthase (complex V) is a peripheral protein complex on the matrix side.\n(iv) FADH₂ formed in the TCA cycle donates its electrons at complex I.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is false: FADH₂ is oxidised by complex II (succinate dehydrogenase), which passes electrons to ubiquinone; complex I is NADH dehydrogenase.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-28","question":"Assertion (A): Cyclic photophosphorylation produces ATP but neither NADPH nor O₂.\nReason (R): It is carried out by photosystem I alone, located in the stroma lamellae, which lack PS II and NADP reductase.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In cyclic flow the electron excited from P700 returns to PS I via the cytochrome b₆f complex, pumping protons and making ATP only. Water splitting (O₂) needs PS II and NADPH needs NADP reductase, both absent in stroma lamellae.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-29","question":"Match the respiratory substrate with its approximate respiratory quotient.\nA. Carbohydrate — 1. About 0.7\nB. Fat — 2. More than 1\nC. Protein — 3. 1.0\nD. Organic acid (e.g. malic acid) — 4. About 0.9","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-1, B-3, C-2, D-4","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Carbohydrates give RQ = 1; fats, being poor in oxygen, consume more O₂ (RQ ≈ 0.7); proteins ≈ 0.9; organic acids are already rich in oxygen so release more CO₂ than O₂ used (RQ > 1).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-30","question":"Which of the following is NOT correctly matched (growth regulator — discovery)?","options":["Gibberellin — E. Kurosawa, from ‘bakanae’ (foolish seedling) disease of rice caused by Gibberella fujikuroi","Kinetin — F. Skoog and C. Miller, from autoclaved herring sperm DNA","Zeatin — isolated from coconut milk and corn kernels","Ethylene — identified by Charles Darwin from ripe oranges hastening ripening of bananas"],"answer":3,"explanation":"Cousins (1910) noted that a gas from ripened oranges hastened ripening of stored bananas, later identified as ethylene. Darwin’s work was on phototropism of canary-grass coleoptiles, which led to the discovery of auxin.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-31","question":"The chief pigment associated with photosynthesis, forming the reaction centre, is:","options":["Chlorophyll b","Chlorophyll a","Carotene","Xanthophyll"],"answer":1,"explanation":"Chlorophyll a is the chief pigment and forms the reaction centre; chlorophyll b, xanthophylls and carotenoids are accessory pigments that widen the range of usable light.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-physiology-32","question":"The reaction centres of photosystem I and photosystem II are respectively:","options":["P700 and P680","P680 and P680","P700 and P700","P680 and P700"],"answer":0,"explanation":"PS I has its absorption peak at 700 nm (P700) and PS II at 680 nm (P680).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-33","question":"The splitting of water during the light reaction is associated with:","options":["Photosystem II, on the lumen side of the thylakoid","The Calvin cycle, in the stroma of the chloroplast","Photosystem I, on the stroma side of the thylakoid","The outer membrane of the chloroplast envelope"],"answer":0,"explanation":"The water-splitting complex is associated with PS II on the inner side (lumen side) of the thylakoid membrane; it supplies electrons to replace those lost by PS II and releases O₂.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-34","question":"Guttation, the loss of water as liquid droplets from leaf tips and margins, occurs through:","options":["Lenticels","Hydathodes","Open stomata","Cuticle"],"answer":1,"explanation":"Under high root pressure, water oozes out through special openings of veins near the leaf tips called hydathodes. Transpiration, in contrast, is loss of water vapour mainly through stomata.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-35","question":"In glycolysis, ATP is formed directly (substrate-level phosphorylation) during the conversion of:","options":["Glyceraldehyde-3-phosphate to 1,3-bisphosphoglycerate","Fructose-6-phosphate to fructose-1,6-bisphosphate","Glucose to glucose-6-phosphate by hexokinase","BPGA to 3-phosphoglycerate, and PEP to pyruvate"],"answer":3,"explanation":"ATP is made when BPGA becomes PGA and when PEP becomes pyruvate. ATP is used in the two phosphorylation steps on glucose and fructose-6-phosphate, and the oxidation of PGAL forms NADH.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-36","question":"The law of limiting factors, which states that when a process is affected by several factors its rate depends on the factor nearest its minimal value, was given by:","options":["Hatch and Slack","Blackman (1905)","Jan Ingenhousz","Melvin Calvin"],"answer":1,"explanation":"Blackman's law of limiting factors (1905). Calvin worked out the C3 pathway, Hatch and Slack the C4 pathway, and Ingenhousz showed that sunlight is essential for plants to purify air.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-37","question":"Leghaemoglobin, the pink pigment of legume root nodules, acts as:","options":["An O₂ scavenger that protects nitrogenase","A carrier of electrons in photosynthesis","A storage form of nitrogen in the nodule","The enzyme that reduces N₂ to NH₃ directly"],"answer":0,"explanation":"Nitrogenase is sensitive to oxygen; leghaemoglobin scavenges O₂ in the nodule and keeps the environment suitable for nitrogen fixation.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-38","question":"Water and minerals entering the root through the apoplast must pass through the symplast at the endodermis because:","options":["Plasmodesmata are absent between the cortical cells","The endodermal cells have no plasma membrane at all","Xylem vessels open directly into the cortex at the endodermis","The suberised Casparian strip of the endodermis blocks water"],"answer":3,"explanation":"The suberised Casparian strip blocks apoplastic movement, so water and solutes must cross the endodermal plasma membranes; this lets the root regulate the quantity and type of solutes reaching the xylem.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-39","question":"How many of the following statements about plant growth are correct?\n(i) Growth is an irreversible permanent increase in the size of an organ, its parts or an individual cell.\n(ii) Arithmetic growth is expressed as Lₜ = L₀ + rt.\n(iii) Geometric growth is expressed as W₁ = W₀eʳᵗ.\n(iv) If two leaves of different sizes increase by the same area in a given time, the smaller leaf has the higher relative growth rate.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Relative growth rate is growth per unit time divided by the initial size, so the same absolute increase gives a higher rate for the smaller leaf.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-40","question":"To make 3 molecules of glucose, how many turns of the Calvin cycle are needed, and how many ATP molecules are used?","options":["6 turns and 18 ATP","18 turns and 54 ATP","18 turns and 36 ATP","3 turns and 54 ATP"],"answer":1,"explanation":"One glucose needs 6 turns, 18 ATP and 12 NADPH. For 3 glucose: 6 × 3 = 18 turns and 18 × 3 = 54 ATP (and 36 NADPH).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-41","question":"Match the process of the nitrogen cycle with the organism.\nList I: (A) Ammonia to nitrite (B) Nitrite to nitrate (C) Denitrification (D) Free-living aerobic nitrogen fixation\nList II: (1) Pseudomonas and Thiobacillus (2) Azotobacter (3) Nitrosomonas or Nitrococcus (4) Nitrobacter","options":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2"],"answer":1,"explanation":"Nitrosomonas/Nitrococcus oxidise ammonia to nitrite and Nitrobacter oxidise nitrite to nitrate (nitrification); Pseudomonas and Thiobacillus reduce nitrate to N₂ (denitrification); Azotobacter is a free-living aerobic N₂ fixer.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-42","question":"Assertion (A): Photorespiration is a wasteful process.\nReason (R): In photorespiration there is no synthesis of ATP or NADPH; instead ATP is used and CO₂ is released.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: when RuBisCO binds O₂ instead of CO₂, no sugar is made, energy is consumed and fixed carbon is lost as CO₂.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-43","question":"How many of the following statements about respiration are correct?\n(i) In alcoholic fermentation by yeast, pyruvic acid is converted to CO₂ and ethanol by pyruvic acid decarboxylase and alcohol dehydrogenase.\n(ii) Yeasts can tolerate alcohol concentrations up to about 50%.\n(iii) Pyruvate dehydrogenase works in the cytoplasm.\n(iv) The TCA cycle starts with condensation of the acetyl group with oxaloacetic acid and water to form citric acid.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iv) are correct. Yeasts poison themselves at an alcohol concentration of about 13%, and the oxidative decarboxylation of pyruvate by pyruvate dehydrogenase occurs in the mitochondrial matrix.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-44","question":"All of the following are functions of ethylene EXCEPT:","options":["Promoting rapid internode elongation in deep water rice plants","Initiating flowering and synchronising fruit set in pineapple","Promoting bolting just before flowering in cabbage","Promoting the formation of female flowers in cucumbers"],"answer":2,"explanation":"Bolting in cabbage and beet is promoted by gibberellins. Ethylene promotes female flowers in cucumber, flowering in pineapple, internode elongation in deep water rice, fruit ripening and senescence.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-45","question":"How many of the following statements about mineral nutrition are correct?\n(i) Manganese toxicity may induce deficiencies of iron, magnesium and calcium.\n(ii) The prominent symptom of manganese toxicity is brown spots surrounded by chlorotic veins.\n(iii) The technique of hydroponics was first demonstrated by Melvin Calvin.\n(iv) Deficiency symptoms of mobile elements such as N, K and Mg appear first in younger tissues.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"(i) and (ii) are correct. (iii) is wrong: hydroponics was demonstrated by Julius von Sachs in 1860. (iv) is wrong: deficiency of mobile elements shows first in older tissues, since they are moved to the young ones.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-plant-physiology-46", "question": "Glycolysis, the partial oxidation of glucose to pyruvic acid, takes place in the:", "options": ["Inner mitochondrial membrane", "Mitochondrial matrix", "Chloroplast stroma", "Cytoplasm"], "answer": 3, "explanation": "Glycolysis occurs in the cytoplasm of all living organisms. The TCA cycle takes place in the mitochondrial matrix and ETS in the inner membrane.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-47", "question": "Because it increases the tolerance of plants to various kinds of stress, abscisic acid is also called the:", "options": ["Youth hormone", "Ripening hormone", "Stress hormone", "Bolting hormone"], "answer": 2, "explanation": "ABA is called the stress hormone; it stimulates stomatal closure and increases tolerance to stresses. Ethylene is the ripening hormone.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-48", "question": "The action spectrum of photosynthesis shows that most photosynthesis takes place in the:", "options": ["Blue and red regions of the spectrum", "Ultraviolet region only", "Infrared region", "Green and yellow regions of the spectrum"], "answer": 0, "explanation": "The action spectrum closely matches the absorption spectrum of chlorophyll a, with maxima in the blue and red regions; green light is mostly reflected.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-49", "question": "The conversion of one molecule of pyruvic acid into acetyl CoA in the mitochondrial matrix yields:", "options": ["One ATP and one FADH₂", "Two CO₂ and two NADH", "One CO₂ and one FADH₂", "One CO₂ and one NADH"], "answer": 3, "explanation": "Pyruvate dehydrogenase carries out oxidative decarboxylation: pyruvic acid + CoA + NAD⁺ → acetyl CoA + CO₂ + NADH + H⁺. Two of each are formed per glucose, not per pyruvate.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-50", "question": "Auxin was first isolated from:", "options": ["Autoclaved herring sperm DNA", "Human urine", "Corn kernels and coconut milk", "Oat coleoptile tips"], "answer": 1, "explanation": "Auxin (Greek auxein, to grow) was first isolated from human urine. Kinetin came from autoclaved herring sperm DNA and zeatin from corn kernels and coconut milk.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-51", "question": "Zeatin, a natural substance with cytokinin-like activity, was isolated from:", "options": ["Ripened oranges", "Corn kernels and coconut milk", "Human urine", "The fungus Gibberella fujikuroi"], "answer": 1, "explanation": "After kinetin was discovered from autoclaved herring sperm DNA, zeatin was isolated from corn kernels and coconut milk. Gibberella fujikuroi causes bakanae disease of rice and is the source of gibberellins.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-52", "question": "In the TCA cycle, ATP (or GTP) is synthesised directly by substrate-level phosphorylation during the conversion of:", "options": ["Acetyl CoA to citric acid", "Malic acid to oxaloacetic acid", "Succinyl CoA to succinic acid", "Citric acid to isocitric acid"], "answer": 2, "explanation": "During the conversion of succinyl CoA to succinic acid, one GTP is formed by substrate-level phosphorylation, which can be converted to ATP. Malic acid to OAA yields NADH.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-53", "question": "In C4 plants, the first stable product of CO₂ fixation in mesophyll cells is:", "options": ["Ribulose bisphosphate (5C)", "Oxaloacetic acid (4C)", "Phosphoenol pyruvate (3C)", "3-phosphoglyceric acid (3C)"], "answer": 1, "explanation": "PEP (3C) accepts CO₂ in mesophyll cells under PEP carboxylase, forming oxaloacetic acid, a 4-carbon acid; hence the name C4 pathway. PGA is the first product in C3 plants.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-plant-physiology-54","question":"In the C4 pathway, after the C4 acid releases CO₂ in the bundle-sheath cells, the 3-carbon molecule formed:","options":["Is fully respired to CO₂ in the bundle sheath mitochondria","Returns to the mesophyll and is converted back to PEP","Is converted to RuBP in the mesophyll chloroplasts","Enters the Calvin cycle directly as 3-PGA"],"answer":1,"explanation":"The C4 acid is broken down in the bundle sheath to release CO₂ (fixed by RuBisCO in the Calvin cycle) and a 3-carbon molecule, which returns to the mesophyll where it is converted back to PEP, completing the cycle.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-55","question":"When fats are used as respiratory substrates, glycerol enters the respiratory pathway after being converted to:","options":["PGAL (a triose phosphate)","Oxaloacetic acid (OAA)","Pyruvic acid","Acetyl CoA, like fatty acids"],"answer":0,"explanation":"Fats are broken into glycerol and fatty acids; fatty acids are degraded to acetyl CoA, while glycerol is converted into PGAL and enters glycolysis.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-plant-physiology-56", "question": "According to NCERT, spraying a sugarcane crop with gibberellins can increase the yield by as much as:", "options": ["2 tonnes per acre", "20 kg per acre", "200 tonnes per acre", "20 tonnes per acre"], "answer": 3, "explanation": "Sugarcane stores sugar in its stem; gibberellins increase stem length, raising the yield by as much as 20 tonnes per acre.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-plant-physiology-57","question":"The synthetic auxin 2,4-D is widely used as a weedicide because it:","options":["Kills dicot weeds but spares mature monocots","Kills monocotyledonous weeds but does not affect dicots","Kills all plants equally, acting as a general poison","Only inhibits seed germination of weeds in the soil"],"answer":0,"explanation":"2,4-D kills dicot weeds without affecting mature monocots, so it is used to prepare weed-free lawns and in cereal crops.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-58","question":"In both lactic acid and alcoholic fermentation, the fraction of the energy in glucose that is released is:","options":["Under 7%","About 70%","About 40%","Nearly 100%"],"answer":0,"explanation":"In fermentation glucose is only partially oxidised, and less than seven per cent of its energy is released, not all of it trapped as ATP. Aerobic respiration oxidises glucose completely to CO₂ and water.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-59","question":"Melvin Calvin worked out that the first CO₂ fixation product in C3 plants is 3-phosphoglyceric acid by using:","options":["Radioactive ¹⁴C in algal photosynthesis","X-ray diffraction of isolated chloroplasts","Heavy oxygen ¹⁸O in the supplied water","Purple and green sulphur bacteria"],"answer":0,"explanation":"Calvin used radioactive ¹⁴C in algal photosynthesis studies, which led to the discovery that the first CO₂ fixation product was a 3-carbon organic acid, PGA. Van Niel used sulphur bacteria to show O₂ comes from water.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-60","question":"How many of the following statements about chemiosmotic ATP synthesis in chloroplasts are correct?\n(i) Protons accumulate inside the thylakoid lumen.\n(ii) Splitting of water occurs on the inner side of the thylakoid membrane.\n(iii) NADP reductase is located on the stroma side of the membrane.\n(iv) The CF₀ part of ATP synthase protrudes on the outer surface of the thylakoid facing the stroma.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is wrong: CF₀ is embedded in the thylakoid membrane and forms a transmembrane channel for protons; it is CF₁ that protrudes on the outer surface facing the stroma.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-plant-physiology-61", "question": "Match the pigment with its colour on a paper chromatogram of leaf pigments.\nList I: (A) Chlorophyll a (B) Chlorophyll b (C) Xanthophylls (D) Carotenoids\nList II: (1) Yellow (2) Bright or blue green (3) Yellow to yellow-orange (4) Yellow green", "options": ["A-4, B-2, C-1, D-3", "A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-2, B-4, C-3, D-1"], "answer": 1, "explanation": "Chromatography separates chlorophyll a (bright or blue green), chlorophyll b (yellow green), xanthophylls (yellow) and carotenoids (yellow to yellow-orange).", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-62", "question": "Assertion (A): Fermentation yields far less energy per glucose than aerobic respiration.\nReason (R): In fermentation, glucose is only partially oxidised, to compounds such as ethanol or lactic acid.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Because the products of fermentation still contain much of the energy of glucose, only 2 ATP are gained per glucose, against many more when glucose is oxidised fully to CO₂ and H₂O.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-63", "question": "Using the NCERT values of 3 ATP per NADH and 2 ATP per FADH₂, how many ATP are produced from the complete aerobic oxidation of ONE molecule of pyruvic acid (link reaction + TCA cycle + ETS)?", "options": ["12", "15", "30", "18"], "answer": 1, "explanation": "Link reaction: 1 NADH = 3 ATP. TCA cycle: 3 NADH = 9 ATP, 1 FADH₂ = 2 ATP and 1 GTP/ATP = 1. Total = 3 + 9 + 2 + 1 = 15 ATP. Forgetting the link-reaction NADH gives 12.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-64", "question": "Arrange the following intermediates of the TCA cycle in the order in which they are formed, starting after acetyl CoA enters:\n(i) Malic acid (ii) Citric acid (iii) α-Ketoglutaric acid (iv) Succinyl CoA", "options": ["(iii), (ii), (iv), (i)", "(ii), (iv), (iii), (i)", "(ii), (iii), (i), (iv)", "(ii), (iii), (iv), (i)"], "answer": 3, "explanation": "Acetyl CoA condenses with OAA to form citric acid, which is converted to α-ketoglutaric acid, then succinyl CoA, then (via succinic acid) malic acid, which is oxidised back to OAA.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-plant-physiology-65","question":"All of the following are effects of abscisic acid EXCEPT:","options":["It promotes seed germination","It stimulates the closure of stomata","It inhibits seed germination","It induces seed and bud dormancy"],"answer":0,"explanation":"ABA inhibits germination, closes stomata, increases stress tolerance and induces seed dormancy, so it generally acts as an antagonist of gibberellins. Promoting germination is a gibberellin effect.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-66","question":"How many of the following are assumptions made when calculating a net gain of 38 ATP per glucose in aerobic respiration?\n(i) There is a sequential, orderly pathway, with glycolysis followed by ETS and then the TCA cycle.\n(ii) The NADH synthesised in glycolysis is transferred into the mitochondria and undergoes oxidative phosphorylation.\n(iii) Some intermediates of the pathway are drawn off to synthesise fatty acids and amino acids.\n(iv) Alternative substrates such as fats and proteins enter the pathway at intermediate stages.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only (ii) is an NCERT assumption. The calculation assumes glycolysis, then TCA, then ETS; that no intermediate is used to make another compound; and that only glucose is respired, with no alternative substrates entering.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-plant-physiology-67", "question": "Match the term with its description.\nList I: (A) Plasticity (B) Dedifferentiation (C) Differentiation (D) Redifferentiation\nList II: (1) Cells derived from meristems mature to perform specific functions (2) Ability to follow different pathways in response to environment or phase of life, as in heterophylly (3) Cells produced by dedifferentiated tissue again lose the capacity to divide and mature (4) Living differentiated cells regain the capacity to divide, as in formation of interfascicular cambium", "options": ["A-2, B-1, C-4, D-3", "A-2, B-4, C-3, D-1", "A-4, B-2, C-1, D-3", "A-2, B-4, C-1, D-3"], "answer": 3, "explanation": "Plasticity is seen in heterophylly (cotton, coriander, larkspur); interfascicular cambium arising from parenchyma is dedifferentiation; maturation of meristem-derived cells is differentiation; and cells from such tissue maturing again is redifferentiation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-68", "question": "Assertion (A): The respiratory pathway is considered an amphibolic pathway.\nReason (R): It is involved in both catabolism and anabolism; for example, fatty acids broken down to acetyl CoA for respiration can also be synthesised from acetyl CoA withdrawn from the pathway.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Since the same pathway breaks down substrates and also supplies intermediates for synthesis of fats and amino acids, it is better called amphibolic than purely catabolic.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-69", "question": "How many of the following statements about growth in plants are correct?\n(i) Cells in the meristematic phase are rich in protoplasm, have large nuclei and thin cellulosic primary walls with abundant plasmodesmata.\n(ii) The phase of elongation shows increased vacuolation, cell enlargement and new cell wall deposition.\n(iii) Cells in the phase of maturation attain their maximal size in terms of wall thickening and protoplasmic modification.\n(iv) A typical growth curve of a cell, tissue or organism is sigmoid, with lag, log (exponential) and stationary phases.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct NCERT statements on the phases of growth and the sigmoid growth curve.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-plant-physiology-70", "question": "Which of the following is NOT a function of gibberellins?", "options": ["Speeding up the malting process in the brewing industry", "Bolting (internode elongation just before flowering) in beet and cabbage", "Increasing the length of grape stalks", "Promoting the abscission of leaves and fruits"], "answer": 3, "explanation": "Gibberellins elongate grape stalks, cause bolting in rosette plants, speed malting and delay senescence. Abscission of plant parts is promoted by ethylene and ABA, not by gibberellins.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-plant-physiology-71","question":"Accessory photosynthetic pigments such as chlorophyll b, xanthophylls and carotenoids:","options":["Act as the reaction centre of both PS I and PS II in place of chlorophyll a","Split water to release oxygen on the lumen side","Pass absorbed energy to chlorophyll a and shield it from photo-oxidation","Fix CO₂ in the stroma along with RuBisCO"],"answer":2,"explanation":"Accessory pigments widen the range of wavelengths used, pass the energy on to chlorophyll a, and protect it from photo-oxidation. The reaction centre itself is chlorophyll a.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-physiology-72","question":"In aerobic respiration, the final acceptor of electrons (hydrogen) at the end of the electron transport system is:","options":["NAD⁺","FAD","Cytochrome c","Oxygen"],"answer":3,"explanation":"Molecular O₂ accepts electrons at complex IV and combines with protons to form water. NAD⁺ and FAD are intermediate carriers, and cytochrome c is a mobile carrier between complexes III and IV.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-physiology-73","question":"The most abundant enzyme in the world is:","options":["RuBisCO","PEP carboxylase","ATP synthase","Hexokinase"],"answer":0,"explanation":"RuBisCO (ribulose bisphosphate carboxylase-oxygenase) catalyses CO₂ fixation in the Calvin cycle of all photosynthetic plants and is present in very large amounts in leaves.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-plant-physiology-74","question":"In the Calvin cycle, the stage that uses both ATP and NADPH is:","options":["Reduction","Carboxylation","Regeneration","Photolysis"],"answer":0,"explanation":"In reduction, 3-PGA is converted to carbohydrate using 2 ATP and 2 NADPH per CO₂ fixed. Regeneration of RuBP needs only ATP, carboxylation needs neither, and photolysis is part of the light reaction.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-75","question":"In the non-cyclic light reaction, electron flow from PS II through the carriers to PS I and then to NADP⁺ is called the Z scheme because:","options":["Electrons move in a zig-zag path back and forth across the stroma","The carriers, plotted on a redox potential scale, form a Z shape","It was discovered by a scientist whose name begins with Z","It happens only in the zeaxanthin-containing grana"],"answer":1,"explanation":"The Z scheme is named after its shape: electrons are excited uphill at PS II, move downhill through the carriers, and are excited uphill again at PS I before reaching NADP⁺.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-76","question":"The interfascicular cambium and the cork cambium of dicot plants are formed from fully differentiated living cells by the process of:","options":["Redifferentiation","Differentiation","Dedifferentiation","Senescence"],"answer":2,"explanation":"Mature parenchyma cells regain the capacity to divide (dedifferentiation) to form these meristems. The cells they produce then lose that capacity again as they mature, which is redifferentiation.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-77","question":"Which of the following is a NATURAL auxin isolated from plants?","options":["NAA (naphthalene acetic acid)","2,4-D","Ethephon","IBA (indole butyric acid)"],"answer":3,"explanation":"IAA and IBA have been isolated from plants. NAA and 2,4-D are synthetic auxins, and ethephon is a synthetic source of ethylene.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-78","question":"Which statement about gibberellins is correct?","options":["Only one gibberellin, GA₃, exists in nature; the rest are synthetic","Over 100 are known, all acidic; GA₃ was among the first discovered","Gibberellins are gaseous hormones, like ethylene","Gibberellins are found only in fungi such as Gibberella"],"answer":1,"explanation":"Over 100 gibberellins (GA₁, GA₂, GA₃ and so on) have been reported from fungi and higher plants. All are acidic, and GA₃ remains the most intensively studied.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-79","question":"In each photosystem, the light harvesting complex (antenna) consists of:","options":["A single chlorophyll a molecule, with no accessory pigments","Only carotenoids, which pass their electrons directly to NADP⁺ reductase","Many pigment-protein complexes around one chlorophyll a reaction centre","The ATP synthase complex together with the cytochromes"],"answer":2,"explanation":"All pigments of a photosystem except one chlorophyll a molecule form the light harvesting system. That one chlorophyll a is the reaction centre: P680 in PS II and P700 in PS I.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-plant-physiology-80","question":"In glycolysis, NADH + H⁺ is formed during the conversion of:","options":["Glucose to glucose-6-phosphate","Phosphoenolpyruvate to pyruvic acid","Fructose-6-phosphate to fructose-1,6-bisphosphate","PGAL to 1,3-bisphosphoglycerate (BPGA)"],"answer":3,"explanation":"PGAL is oxidised, with inorganic phosphate added, to BPGA, and NAD⁺ is reduced to NADH + H⁺. The other three steps are phosphorylations (using ATP) or substrate-level ATP formation, with no NADH produced.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-81","question":"When fats are used as respiratory substrates, the fatty acids enter the respiratory pathway after being degraded to:","options":["Acetyl CoA","Glycerol","Phosphoglyceraldehyde","Phosphoenolpyruvate"],"answer":0,"explanation":"Fatty acids are broken down to acetyl CoA, which enters the Krebs cycle. Glycerol, the other part of a fat, enters glycolysis as PGAL. This entry at different points makes respiration amphibolic.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-82","question":"In fruits, ethylene enhances the rate of respiration during ripening. This rise in the rate of respiration is called the:","options":["Respiratory climacteric","Photorespiratory burst","Pasteur effect in fruits","Fermentation phase"],"answer":0,"explanation":"The burst of respiration during ripening caused by ethylene is called the respiratory climacteric. Photorespiration is a light-dependent oxygenation by RuBisCO, which has nothing to do with fruit ripening.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-83","question":"Abscisic acid was discovered independently in three different studies, under the names:","options":["Auxin a, auxin b and heteroauxin","Inhibitor-B, abscission II and dormin","Kinetin, zeatin and coconut milk factor","Florigen, vernalin and dormin"],"answer":1,"explanation":"Three kinds of inhibitors (inhibitor-B, abscission II and dormin) turned out to be chemically identical and were named abscisic acid (ABA). Kinetin and zeatin are cytokinins.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-84","question":"Spraying juvenile conifers with gibberellins:","options":["Induces dormancy of their apical buds","Promotes early abscission of their needles","Hastens their maturity, so seeds form early","Converts them into dwarf, rosette-like plants"],"answer":2,"explanation":"Gibberellins shorten the juvenile period of conifers, so seeds are produced earlier. Bud dormancy and abscission are promoted by ABA (and ethylene), not by gibberellins.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-85","question":"In C4 plants, the 4-carbon compounds that are transported from the mesophyll cells to the bundle-sheath cells are:","options":["3-PGA or ribulose bisphosphate","Pyruvic acid or phosphoenolpyruvate","Glucose or sucrose","Malic acid or aspartic acid"],"answer":3,"explanation":"OAA formed in the mesophyll is converted to malic or aspartic acid and sent to the bundle sheath, where it releases CO₂ for RuBisCO. The 3-carbon pyruvate returns to the mesophyll to regenerate PEP.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-86","question":"Cyclic photophosphorylation, besides occurring in the stroma lamellae, also occurs when:","options":["Only blue light of 450 nm is available for excitation","Only light beyond 680 nm is available for excitation","CO₂ concentration around the leaf is very high","The plant is kept in complete darkness for hours"],"answer":1,"explanation":"Light beyond 680 nm excites PS I (P700) but not PS II (P680). Only cyclic electron flow around PS I can then run, making ATP without NADPH or O₂. No light reaction occurs in darkness.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-87","question":"In cotton, coriander and larkspur, the leaves of the juvenile plant differ in shape from those of the mature plant. This is an example of:","options":["Dedifferentiation of tissues","Apical dominance by auxins","Plasticity (heterophylly)","Vernalisation"],"answer":2,"explanation":"Plants can follow different pathways to form different structures, which is plasticity. Heterophylly in cotton, coriander and larkspur is developmental, while in buttercup the difference between aerial and submerged leaves is due to the environment.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-88","question":"According to NCERT, during ATP synthesis by the F₀–F₁ ATP synthase of mitochondria, for each ATP produced:","options":["2 H⁺ pass through F₁ from the matrix to the intermembrane space","1 electron passes through F₀ to oxygen","4 H⁺ are pumped against their gradient using the ATP","2 H⁺ pass through F₀ from the intermembrane space to the matrix"],"answer":3,"explanation":"Protons flow down their electrochemical gradient through the F₀ channel into the matrix, and this flow drives ATP formation at F₁. NCERT states 2 H⁺ per ATP. F₁ is the peripheral headpiece where ATP is actually made.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-89","question":"Water stress reduces the rate of photosynthesis mainly because:","options":["Stomata close, cutting CO₂ supply, and wilting reduces leaf area and metabolism","Water is the main limiting raw material, as so much of it is used in photolysis","Chlorophyll is washed out of the leaves","RuBisCO is converted into PEP carboxylase"],"answer":0,"explanation":"Water's effect on photosynthesis is mostly indirect, through its effect on the plant. Only a small fraction of absorbed water is used in photolysis, so lack of water as a raw material is not the main cause.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-90","question":"The scheme of glycolysis was worked out by:","options":["Embden, Meyerhof and Parnas","Hans Krebs and William Johnson","Melvin Calvin and Andrew Benson","Marshall Hatch and Roger Slack"],"answer":0,"explanation":"Glycolysis is also called the EMP pathway after Embden, Meyerhof and Parnas. Krebs described the citric acid cycle, Calvin the C3 cycle, and Hatch and Slack the C4 pathway.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-91","question":"Using the NCERT values (NADH = 3 ATP, FADH₂ = 2 ATP), how many ATP are produced from the complete aerobic oxidation of ONE molecule of pyruvic acid (link reaction plus one turn of the Krebs cycle)?","options":["12","15","38","30"],"answer":1,"explanation":"Link reaction: 1 NADH = 3 ATP. Krebs cycle: 3 NADH = 9, 1 FADH₂ = 2 and 1 GTP/ATP = 1. Total 3 + 9 + 2 + 1 = 15 ATP. Two pyruvates give 30, and with glycolysis (8) the total is 38. 12 is the yield of acetyl CoA alone.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-92","question":"In response to increasing CO₂ concentration under high light, C4 plants show saturation at about ______ µL/L, while C3 plants show saturation only beyond ______ µL/L.","options":["450; 360","100; 200","360; 450","3000; 4500"],"answer":2,"explanation":"C4 plants saturate at about 360 µL/L, while C3 plants keep responding and saturate only beyond 450 µL/L. This is why C3 crops such as tomato and bell pepper give higher yields in CO₂-enriched greenhouses.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-93","question":"How many of the following statements about auxins are correct?\n(i) They help to initiate rooting in stem cuttings.\n(ii) They prevent fruit and leaf drop at early stages.\n(iii) They promote abscission of older, mature leaves and fruits.\n(iv) They induce parthenocarpy, for example in tomato.\n(v) 2,4-D is used to kill monocot weeds without affecting dicot crops.","options":["One","Two","Three","Four"],"answer":3,"explanation":"Statements (i) to (iv) are correct. (v) is reversed: 2,4-D removes broad-leaved dicot weeds and does not affect mature monocots, which is why it is used in lawns and cereal fields.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-94","question":"Match the plant growth regulator with its chemical nature.\nList I: (A) IAA (B) Kinetin (C) Abscisic acid (D) GA₃\nList II: (1) Derivative of carotenoids (2) Terpene (3) Indole compound (4) Adenine (purine) derivative","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":1,"explanation":"IAA is an indole compound, kinetin an adenine derivative, ABA a carotenoid derivative and GA₃ a terpene. Ethylene, the fifth major PGR, is a gas.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-95","question":"Using the NCERT values (NADH = 3 ATP), how many ATP are obtained per glucose from glycolysis alone, when the NADH formed is oxidised in the mitochondria under aerobic conditions?","options":["2","6","8","4"],"answer":2,"explanation":"Net substrate-level ATP = 2, and 2 NADH × 3 = 6, giving 8 ATP. 2 is the net gain under anaerobic conditions, and 4 is the gross substrate-level yield before subtracting the 2 ATP invested.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-96","question":"How many of the following statements about factors affecting photosynthesis are correct?\n(i) Light saturation occurs at about 10% of full sunlight.\n(ii) CO₂ is a major limiting factor, as its atmospheric concentration is only 0.03–0.04%.\n(iii) Increasing incident light beyond a point causes breakdown of chlorophyll and a fall in photosynthesis.\n(iv) C4 plants respond to higher temperatures and show a higher rate of photosynthesis.\n(v) Tomatoes and bell pepper grown in CO₂-enriched greenhouses give higher yields.","options":["Two","Three","Four","Five"],"answer":3,"explanation":"All five statements match NCERT. Because light saturates at low intensity, light is rarely limiting except for plants in shade or dense forests, while CO₂ often is.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-97","question":"Assertion (A): In C3 plants, some O₂ binds to RuBisCO, which decreases CO₂ fixation.\nReason (R): RuBisCO has a much greater affinity for O₂ than for CO₂.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true; this is photorespiration. R is false: RuBisCO has a much greater affinity for CO₂. Which gas binds depends on the relative concentrations of O₂ and CO₂.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-98","question":"Arrange the following steps of glycolysis in the correct sequence:\n(i) Fructose-6-phosphate is phosphorylated to fructose-1,6-bisphosphate\n(ii) Glucose is phosphorylated to glucose-6-phosphate\n(iii) PGAL is oxidised to BPGA with formation of NADH\n(iv) Fructose-1,6-bisphosphate splits into DHAP and PGAL\n(v) PEP is converted to pyruvic acid with formation of ATP","options":["(ii), (iv), (i), (iii), (v)","(i), (ii), (iv), (iii), (v)","(ii), (i), (iv), (iii), (v)","(ii), (i), (iii), (iv), (v)"],"answer":2,"explanation":"Glucose is first phosphorylated by hexokinase, then fructose-6-phosphate is phosphorylated again. The 6-carbon sugar splits into two triose phosphates, PGAL is oxidised (NADH), and finally PEP gives pyruvate with ATP formation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-99","question":"In the same period, leaf A grows from 5 cm² to 10 cm² and leaf B from 50 cm² to 60 cm². Which statement is correct?","options":["A shows both the greater absolute growth and the greater relative growth rate","B has the greater absolute growth, but A the greater relative growth rate","B shows both the greater absolute growth and the greater relative growth rate","Both show the same relative growth rate"],"answer":1,"explanation":"Absolute growth: A = 5 cm², B = 10 cm². Relative growth (gain divided by initial size): A = 5/5 = 100%, B = 10/50 = 20%. So B has more absolute growth but A grows faster relative to its size.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-100","question":"Match the enzyme with the reaction or role.\nList I: (A) Hexokinase (B) Pyruvate dehydrogenase (C) Alcohol dehydrogenase (D) Lactate dehydrogenase\nList II: (1) Reduction of pyruvic acid to lactic acid in muscle during oxygen shortage (2) Glucose to glucose-6-phosphate (3) Pyruvic acid to acetyl CoA in the mitochondrial matrix (4) Formation of ethanol in yeast fermentation","options":["A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1"],"answer":1,"explanation":"Hexokinase phosphorylates glucose. Pyruvate dehydrogenase makes acetyl CoA in the matrix, with NAD⁺ and coenzyme A. Alcohol dehydrogenase works with pyruvic acid decarboxylase to form ethanol, and lactate dehydrogenase reduces pyruvate to lactate using NADH.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-plant-physiology-101","question":"In T. W. Engelmann's experiment, the green alga Cladophora was illuminated with light split by a prism, with aerobic bacteria added. The bacteria accumulated mainly in:","options":["the blue and red regions, giving the first action spectrum of photosynthesis","the green region, since green light is the most strongly absorbed by chlorophyll","the yellow and orange regions, where the carotenoids absorb the most light","the far-red region, which alone drives photosystem II of the chloroplast"],"answer":0,"explanation":"Aerobic bacteria gathered where O₂ evolution was highest — in blue and red light — giving the first action spectrum, which roughly resembles the absorption spectra of chlorophyll a and b. Green light is mostly reflected.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-102","question":"In a paper chromatogram of leaf pigments, which pigment is correctly matched with its colour?","options":["Chlorophyll a — yellow green","Chlorophyll a — bright or blue green","Chlorophyll b — bright or blue green","Carotenoids — yellow green"],"answer":1,"explanation":"Chlorophyll a appears bright or blue green, chlorophyll b yellow green, xanthophylls yellow, and carotenoids yellow to yellow-orange. Options A and C swap the two chlorophylls.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-103","question":"Which of the following does NOT contribute to building the proton gradient across the thylakoid membrane during the light reaction?","options":["Splitting of water on the inner (lumen) side of the membrane","Transfer of protons from the stroma to the lumen by an electron carrier","Movement of protons through CF₀ from the lumen back to the stroma","Removal of protons from the stroma by NADP reductase on the stroma side"],"answer":2,"explanation":"Water splitting in the lumen, proton transfer into the lumen by the hydrogen carrier, and NADP reductase removing stromal protons all build the gradient. Proton flow through CF₀ dissipates the gradient and drives ATP synthesis.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-104","question":"Which statement about the ATP synthase of the chloroplast is correct?","options":["CF₁ is embedded in the membrane and CF₀ protrudes into the lumen","CF₀ protrudes into the stroma and CF₁ forms a channel in the lumen","Both CF₀ and CF₁ lie entirely within the thylakoid lumen","CF₀ forms a transmembrane channel; CF₁ faces the stroma"],"answer":3,"explanation":"CF₀ is embedded in the thylakoid membrane and forms a transmembrane channel for facilitated diffusion of protons; CF₁ protrudes on the outer surface facing the stroma, where ATP is made.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-105","question":"Tomatoes and bell peppers are grown in greenhouses with a carbon dioxide-enriched atmosphere. This works because:","options":["C3 plants respond to higher CO₂ with more photosynthesis and yield","C4 plants respond to higher CO₂ far more strongly than C3 plants do","extra CO₂ lowers the light saturation point of these C4 crop plants","high CO₂ increases photorespiration, which then adds to their yield"],"answer":0,"explanation":"C3 plants respond to higher CO₂ with increased photosynthesis and productivity, a fact used for greenhouse crops like tomato and bell pepper. C4 plants saturate at lower CO₂, and high CO₂ actually reduces photorespiration.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-106","question":"Atmospheric CO₂ is about 0.03–0.04 per cent. According to NCERT, raising it up to about what level can increase CO₂ fixation, beyond which it can become damaging over longer periods?","options":["0.01 per cent","0.05 per cent","0.5 per cent","5 per cent"],"answer":1,"explanation":"An increase in CO₂ concentration up to 0.05 per cent can cause an increase in fixation rates; beyond this the levels can become damaging over longer periods.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-107","question":"Which of the following is NOT a feature of the bundle-sheath cells in the leaf of a C4 plant?","options":["They contain a large number of chloroplasts","Their walls are thick and impervious to gaseous exchange","They have large intercellular spaces between them","They may form several layers around the vascular bundles"],"answer":2,"explanation":"Bundle-sheath cells of C4 leaves have many chloroplasts, thick walls impervious to gas exchange and NO intercellular spaces, which keeps the released CO₂ concentrated around RuBisCO.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-108","question":"Melvin Calvin, using radioactive ¹⁴C in algal photosynthesis, found that the first stable product of CO₂ fixation in C3 plants is:","options":["oxaloacetic acid","malic acid","ribulose-1,5-bisphosphate","3-phosphoglyceric acid"],"answer":3,"explanation":"Calvin's work showed that the first CO₂ fixation product is the 3-carbon 3-phosphoglyceric acid (PGA), hence C3. Oxaloacetic acid is the first product in C4 plants.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-physiology-109","question":"The overall equation of photosynthesis is written as 6CO₂ + 12H₂O → C₆H₁₂O₆ + 6H₂O + 6O₂ rather than with 6H₂O on the left. The reason is that:","options":["all six O₂ released come from water, so twelve H₂O are needed","six H₂O make glucose and the other six are used to cool the leaf","the O₂ released comes partly from CO₂ and partly from water","twelve H₂O are needed to regenerate RuBP in the Calvin cycle"],"answer":0,"explanation":"Since all evolved O₂ comes from water (van Niel's insight), 6 O₂ (12 O atoms) require 12 H₂O; the 6 H₂O on the right are formed from CO₂-derived oxygen.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-110","question":"Which of the following is NOT a part of the light reaction of photosynthesis?","options":["Splitting of water by the complex linked with PS II","Reduction of PGA to triose phosphate using ATP and NADPH","Release of oxygen as a by-product of photolysis","Formation of NADPH by the NADP reductase on the stroma side"],"answer":1,"explanation":"Light reactions include light absorption, water splitting, oxygen release and formation of ATP and NADPH. Reduction of PGA to triose phosphate is part of the Calvin cycle in the stroma.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-physiology-111","question":"The stroma lamellae can carry out only cyclic photophosphorylation because their membranes lack:","options":["PS I and the ATP synthase","the cytochrome complex and PS I","PS II and NADP reductase","ATP synthase and plastoquinone"],"answer":2,"explanation":"Stroma lamellae membranes lack PS II as well as NADP reductase, so the excited electron from PS I cannot reduce NADP⁺ and cycles back, producing only ATP.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-112","question":"When sucrose is used as a respiratory substrate, it enters glycolysis after being:","options":["phosphorylated directly by hexokinase in the cytoplasm","converted into maltose by amylase","oxidised to pyruvate by pyruvate dehydrogenase","hydrolysed into glucose and fructose by invertase"],"answer":3,"explanation":"Sucrose is first converted by invertase into glucose and fructose, which are then phosphorylated and enter glycolysis.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-physiology-113","question":"In alcoholic fermentation, yeasts poison themselves to death when the concentration of alcohol reaches about:","options":["13 per cent","3 per cent","30 per cent","50 per cent"],"answer":0,"explanation":"NCERT states that yeasts poison themselves to death when the alcohol concentration reaches about 13 per cent; fermentation also releases less than 7% of the energy in glucose.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-114","question":"During fermentation, the energy released from a molecule of glucose is:","options":["about 40 per cent, all of it trapped in the 38 ATP molecules","less than 7 per cent, and not all of it is trapped as ATP","about 50 per cent, all of it trapped in reduced NADH","exactly 2 per cent, all of it released as body heat"],"answer":1,"explanation":"In both lactic acid and alcoholic fermentation, much less than 7% of the energy in glucose is released, and not all of it is trapped as high-energy bonds of ATP.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-115","question":"The oxidative decarboxylation of pyruvic acid in the mitochondrial matrix requires:","options":["pyruvate decarboxylase with the coenzymes NADH and FAD","lactate dehydrogenase with NAD⁺ and ATP","pyruvate dehydrogenase with NAD⁺ and coenzyme A","citrate synthase with FAD and coenzyme A"],"answer":2,"explanation":"Pyruvic dehydrogenase catalyses the link reaction with the coenzymes NAD⁺ and coenzyme A (and Mg²⁺), giving acetyl CoA, CO₂ and NADH. Pyruvate decarboxylase acts in alcoholic fermentation.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-116","question":"In the Krebs cycle, a molecule of GTP (from which ATP is formed) is synthesised during the conversion of:","options":["citrate to isocitrate","α-ketoglutarate to succinyl-CoA","malate to oxaloacetate","succinyl-CoA to succinic acid"],"answer":3,"explanation":"Conversion of succinyl-CoA to succinic acid allows substrate-level synthesis of GTP, which is converted to GDP with simultaneous synthesis of ATP from ADP. The α-ketoglutarate step is a decarboxylation that forms NADH.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-117","question":"Which statement about the mitochondrial electron transport system is correct?","options":["Cytochrome c oxidase has cytochromes a and a₃ and two copper centres","Complex II passes the electrons from NADH directly to cytochrome c","Ubiquinone carries the electrons from complex III onwards to complex IV","The F₀ part of ATP synthase is the peripheral headpiece making ATP"],"answer":0,"explanation":"Complex IV (cytochrome c oxidase) contains cytochromes a and a₃ and two copper centres. NADH is oxidised by complex I, cytochrome c links complexes III and IV, and F₁ (not F₀) is the headpiece where ATP is made.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-118","question":"When fats are used as respiratory substrates, the glycerol part enters the respiratory pathway after being converted into:","options":["acetyl coenzyme A","PGAL","pyruvic acid","oxaloacetic acid"],"answer":1,"explanation":"Fats are broken into glycerol and fatty acids; glycerol enters as PGAL (3-phosphoglyceraldehyde) in glycolysis, while fatty acids are degraded to acetyl CoA.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-119","question":"Which of the following is NOT one of the assumptions made while calculating the net ATP gain from the aerobic respiration of one glucose molecule?","options":["NADH formed in glycolysis enters the mitochondria and undergoes oxidative phosphorylation","None of the intermediates of the pathway is used to synthesise any other compound","Some acetyl CoA is withdrawn for fatty acid synthesis while respiration goes on","Only glucose is being respired; no alternative substrate enters at any step"],"answer":2,"explanation":"The balance sheet assumes an orderly sequential pathway, entry of glycolytic NADH into oxidative phosphorylation, no withdrawal of intermediates for synthesis, and glucose as the only substrate. Withdrawal of acetyl CoA contradicts these assumptions.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-120","question":"Plants can get along without specialised respiratory organs. Which of the following is NOT a reason given in NCERT?","options":["Each plant part largely takes care of its own gas-exchange needs","Plants do not present great demands for gas exchange","In large plants, gases need not diffuse very far","Plants respire only at night, when the stomata open fully"],"answer":3,"explanation":"Plants respire all the time; NCERT's reasons are that each part handles its own gas exchange, demand is low (except during photosynthesis, when O₂ is generated inside), and in large plants living cells lie close to the surface so diffusion distances are small.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-121","question":"The respiratory pathway is described as amphibolic rather than purely catabolic because:","options":["its intermediates are also used for synthesis, e.g. acetyl CoA","it can proceed both in the presence of oxygen and in its complete absence","it takes place partly in the cytoplasm and partly inside the mitochondria","it can use carbohydrates, fats and proteins alike as respiratory substrates"],"answer":0,"explanation":"The pathway serves both breakdown and synthesis: e.g. fatty acids are broken to acetyl CoA when respired, and acetyl CoA is withdrawn to make fatty acids when needed. Hence it is amphibolic.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-122","question":"In glycolysis, ATP is CONSUMED during the conversion of:","options":["1,3-BPGA → 3-PGA and PEP → pyruvic acid","glucose → G-6-P and F-6-P → F-1,6-bP","PGAL → BPGA and BPGA → PGA","G-6-P → F-6-P and 2-PGA → PEP"],"answer":1,"explanation":"ATP is used when glucose is phosphorylated to glucose-6-phosphate and when fructose-6-phosphate becomes fructose-1,6-bisphosphate. BPGA → PGA and PEP → pyruvate are the ATP-producing steps.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-123","question":"A plant organ grows geometrically according to W₁ = W₀eʳᵗ. If W₀ = 10 g and the relative growth rate r = 0.1 per day, its mass after 10 days is about (take e = 2.718):","options":["20.0 g","11.0 g","27.2 g","100 g"],"answer":2,"explanation":"rt = 0.1 × 10 = 1, so W₁ = 10 × e¹ ≈ 27.2 g. Treating growth as linear (10 × (1 + rt)) gives 20 g, the arithmetic-growth trap.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-124","question":"In arithmetic growth, described by Lₜ = L₀ + rt, following mitotic cell division:","options":["both daughter cells continue to divide repeatedly","both daughter cells stop dividing and mature","the cells divide only after the stationary phase","only one daughter cell divides; the other matures"],"answer":3,"explanation":"In arithmetic growth only one daughter cell continues to divide while the other differentiates and matures, giving a linear curve (e.g. a root elongating at a constant rate). Both cells dividing gives geometric growth.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-125","question":"The difference in shape between the leaves produced in air and those produced in water by the buttercup plant is an example of:","options":["heterophylly due to the environment","heterophylly caused by the life phase","dedifferentiation of mature tissue","apical dominance due to auxin"],"answer":0,"explanation":"Buttercup's leaf shapes differ due to the environment (air vs water), whereas in cotton, coriander and larkspur the juvenile and mature leaves differ due to the phase of life. Both show plasticity.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-126","question":"In 1910, Cousins confirmed the release of a volatile substance that hastened fruit ripening (later identified as ethylene). It was released from:","options":["ripe bananas, and hastened ripening of stored unripe oranges","ripened oranges, and hastened ripening of stored bananas","ripe tomatoes, and hastened ripening of stored unripe apples","ripe apples, and hastened ripening of stored unripe mangoes"],"answer":1,"explanation":"Cousins confirmed that ripened oranges released a volatile substance that hastened the ripening of stored unripened bananas; the substance was later identified as ethylene.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-127","question":"2,4-D is widely used as a weedicide in lawns and cereal fields because it:","options":["kills monocot weeds but spares the mature dicot crops","is a natural auxin that is quickly broken down in soil","kills dicot weeds but does not affect mature monocots","inhibits the germination of all seeds in the field"],"answer":2,"explanation":"2,4-D, a synthetic auxin, is widely used to kill dicotyledonous weeds and does not affect mature monocotyledonous plants, so it keeps lawns and cereal fields weed-free.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-128","question":"Spraying sugarcane with gibberellins increases the length of the stem, increasing the yield by as much as:","options":["2 tonnes per acre","200 tonnes per acre","20 kg per acre","20 tonnes per acre"],"answer":3,"explanation":"Since sugarcane stores carbohydrate as sugar in its stem, spraying gibberellins increases stem length and the yield by as much as 20 tonnes per acre.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-129","question":"The natural cytokinin zeatin was isolated from:","options":["corn kernels and coconut milk","autoclaved herring sperm DNA","rice seedlings infected by a fungus","ripened oranges stored with bananas"],"answer":0,"explanation":"Zeatin was isolated from corn kernels and coconut milk. Kinetin, a modified adenine, came from autoclaved herring sperm DNA, while gibberellins were found from the bakanae disease of rice.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-plant-physiology-130","question":"Ethephon, which releases ethylene, is used to:","options":["promote male flowers in cucumbers and delay the ripening of stored tomatoes","hasten ripening of tomatoes and apples and thin cotton, cherry and walnut","increase the length of grape stalks and elongate apples to improve their shape","speed up the malting process of barley grains in the brewing industry"],"answer":1,"explanation":"Ethephon hastens ripening of tomatoes and apples, accelerates abscission of flowers and fruits (thinning of cotton, cherry, walnut) and promotes FEMALE flowers in cucumbers. Grape stalk length, apple shape and malting are gibberellin uses.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-131","question":"Assertion (A): Abscisic acid is called the stress hormone.\nReason (R): ABA increases the tolerance of plants to various kinds of stress, for example by stimulating closure of stomata.","options":["Both A and R are true, but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"ABA stimulates stomatal closure and increases tolerance to various stresses, which is exactly why it is called the stress hormone.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-132","question":"Which of the following is NOT an endogenous inhibitor causing seed dormancy, as listed in NCERT?","options":["Abscisic acid","Phenolic acids","Para-ascorbic acid","Gibberellic acid"],"answer":3,"explanation":"Inhibitors such as abscisic acid, phenolic acids and para-ascorbic acid cause dormancy; gibberellic acid (and nitrates) are used to overcome it.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-plant-physiology-133","question":"When cells grow in a nutrient-rich medium and their number is plotted against time, the sigmoid curve shows the phases, in order:","options":["lag, log (exponential), stationary","log (exponential), lag, stationary","stationary, lag, log (exponential)","lag, stationary, log (exponential)"],"answer":0,"explanation":"Growth starts slowly (lag phase), then increases rapidly (log or exponential phase), and finally slows down as nutrients become limiting (stationary phase).","difficulty":"moderate","source":"NEET UG"},
];

export default questions;
